const money = (v, c = 'USD') => v == null ? 'Unknown' : new Intl.NumberFormat(undefined, { style: 'currency', currency: c }).format(v);
const percent = v => v == null ? 'Unknown' : `${(v * 100).toFixed(1)}%`;
const time = value => value ? new Date(value).toLocaleString() : 'Never';
const format = w => {
  const p = packageSummary(w), name = w.bottleMl === 1500 ? 'magnum' : w.bottleMl === 3000 ? 'double magnum' : 'bottle';
  return `1 package · ${p.physicalBottles} ${name}${p.physicalBottles === 1 ? '' : 's'} × ${p.bottleMl}ml · ${p.standardBottleEquivalent} × 750ml equivalent · ${w.packaging.toUpperCase()}`;
};
const link = (url, label = 'Source') => /^https?:\/\//.test(url || '') ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>` : '<span>No source URL supplied</span>';
function download(name, value) { const url = URL.createObjectURL(new Blob([value], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 2000); }

