    options('subregion', cachedRows.flatMap(r=>r.vintageIntelligence.geography.path.filter(n=>n.level==='subregion').map(n=>n.name)), 'All subregions / banks');
    options('style', cachedRows.map(r=>r.vintageIntelligence.geography.style), 'All styles / varieties');
