    $('engine-result-count').textContent = `${rows.length} in your filtered universe`;
    const queue = matchQueue(state, cachedRows); $('match-count').textContent = `(${queue.length})`;
    $('engine-results').innerHTML = rows.length ? `<table class="terminal-table"><thead><tr><th>Rank</th><th>Wine / format</th><th>Asking / package</th><th>Market median / package</th><th>Discount</th><th>Critic /100</th><th>Vintage context</th><th>Opportunity</th><th>Evidence</th><th>Details</th></tr></thead><tbody>${pageRows.map(r => `<tr><td class="rank-number">${r.rank}</td><td><strong>${esc(r.wine.rawTitle)}</strong>${r.listing.listingIdentity === 'inferred-offer' ? '<small class="vintage-warning">Separate offer · automatic listing ID · review stock</small>' : ''}<small>${esc(r.listing.sourceName)} · ${esc(r.vintageIntelligence.geography.region || r.wine.region || 'Region unknown')}</small><small>${esc(r.vintageIntelligence.geography.path.filter(n=>['subregion','appellation'].includes(n.level)).map(n=>n.name).join(' → '))}${r.vintageIntelligence.geography.style?' · '+esc(r.vintageIntelligence.geography.style):''}</small><small>${esc(format(r.wine))} · ${r.listing.availableQuantity ?? '?'} packages</small>${r.wine.vintageKind === 'non-vintage' ? '<small>Non-vintage (NV)</small>' : r.wine.vintageKind === 'multi-vintage' ? '<small>Multi-vintage (MV)</small>' : r.wine.vintageKind === 'unknown' && r.wine.rawVintage ? `<small class="vintage-warning">Unknown vintage · import value: ${esc(r.wine.rawVintage)} · review in Explain</small>` : ''}</td><td>${money(r.listing.price, r.listing.currency)}<small>${money(r.listing.unitPrice, r.listing.currency)} / physical bottle</small><small>${money(r.listing.pricePer750, r.listing.currency)} / 750ml equivalent</small></td><td>${money(r.referencePrice == null ? null : r.referencePrice * r.wine.packCount, r.listing.currency)}<small>${r.marketIntelligence.offerCount} confirmed merchant comps · ${r.marketIntelligence.confidenceLabel} confidence</small><small>Lowest ${money(r.marketIntelligence.lowestPrice,r.listing.currency)} / bottle</small></td><td class="${r.discount > 0 ? 'positive' : ''}">${percent(r.discount)}<small>${money(r.marketIntelligence.dollarDiscount==null?null:Math.abs(r.marketIntelligence.dollarDiscount),r.listing.currency)} / bottle ${r.discount<0?'premium':'discount'}</small></td><td>${r.quality == null ? 'No verified score' : r.quality.toFixed(1)}<small>${esc(r.criticStatus)}</small><small>${r.criticComposite.publicationCount} publications · ${r.criticComposite.verifiedCount} verified reviews</small><small>${r.drinkNow == null ? 'Window unknown' : r.drinkNow ? 'In drinking window' : 'Outside window'}</small></td><td>${r.vintage==null?r.vintageIntelligence.notApplicable?'Not applicable':'Not assessed':r.vintage.toFixed(1)+' /100'}<small>${esc(r.vintageIntelligence.tier)} · ${esc(r.vintageIntelligence.confidenceLabel)} confidence</small><small>${esc(r.vintageIntelligence.regionUsed)}</small><button class="button secondary" data-vintage="${esc(r.listing.id)}">Vintage Intelligence</button></td><td><strong>${r.score.toFixed(1)}</strong><small>${esc(r.recommendation)}</small></td><td><span class="coverage-bar"><span style="width:${r.coverage * 100}%"></span></span>${percent(r.coverage)}<small>${r.staleInventory ? 'Inventory stale' : 'As of ' + time(r.listing.observedAt)}</small></td><td><button class="button secondary" data-explain="${esc(r.listing.id)}">Explain</button><button class="button secondary" data-critics="${esc(r.listing.id)}">Professional critics</button><button class="button secondary" data-market="${esc(r.listing.id)}">Market Intelligence</button><button class="button secondary" data-research="${esc(r.listing.id)}">Research prices</button></td></tr>`).join('')}</tbody></table>` : `<div class="terminal-empty"><h3>${state.listings.length ? 'No wines meet these filters.' : 'Start with the wines you can actually buy.'}</h3><p>${state.listings.length ? 'Reset filters or relax an evidence requirement. Missing values do not satisfy minimum-score filters.' : 'Import an authorized Flickinger Excel or CSV inventory export, then add permitted market prices, reviews, and vintage assessments. No live data has been invented.'}</p></div>`;
