  $('engine-import').onclick = () => modal('Import source data', `<p>Upload an Excel (.xlsx), CSV, or JSON export you are permitted to access. Excel uploads include a column-mapping preview. All rows are validated before anything is saved. Price is a package total unless price_basis says bottle; available_quantity counts packages.</p><form id="engine-import-form" class="engine-form"><label>Import source<select name="sourceId">${client.state.sources.filter(s => s.enabled).map(s => `<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.category)}</option>`).join('')}</select></label><label>Excel, CSV or JSON file<input name="file" type="file" accept=".xlsx,.csv,.json,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv,application/json" required></label><label class="engine-check"><input name="complete" type="checkbox">Complete inventory snapshot: mark missing listings unavailable</label><label class="engine-check"><input name="skipInvalidPrices" type="checkbox" checked>Import valid inventory rows and set aside rows with unusable prices</label><p>Excluded rows retain their original data in a downloadable report. A file with excluded rows is treated as a partial snapshot to preserve existing stock.</p><p>This checkbox affects inventory only. Leave it unchecked for partial imports. JSON can also declare completeSnapshot: true.</p><p>Templates: ${['inventory', 'market', 'critic', 'vintage', 'community'].map(k => `<a href="${import.meta.env.BASE_URL}templates/${k}.csv" download>${k} CSV</a>`).join(' · ')}</p><button class="button primary" type="submit">Validate and import</button><p id="engine-form-message" role="status"></p></form>`, 'import');
  $('engine-vintage-charts').onclick = () => {
    $('engine-import').click();
    $('engine-dialog-title').textContent='Your vintage charts';
    $('engine-import-form').elements.sourceId.value='vintage-import';
    const groups=new Map();
    for(const r of getState().vintages) {
      const key=JSON.stringify([r.publication,r.chartName || r.geography?.leafId,r.type,r.style,r.allowedStyles,r.allowedAppellations]);
      if(!groups.has(key)) groups.set(key,[]); groups.get(key).push(r);
    }
    const charts=[...groups.values()];
    $('engine-dialog-body').insertAdjacentHTML('afterbegin', `<p><button class="button primary" id="load-provided-vintage-charts">Load Wine Spectator charts</button> <a href="${import.meta.env.BASE_URL}data/wine-spectator-vintage-charts.json" download="Wine-Spectator-Vintage-Charts.json">Download chart file</a></p><p>Load the 15 provided Wine Spectator charts directly into your saved inventory. No download is needed. Original ratings, chart coverage and source references remain inspectable.</p><p id="provided-vintage-chart-status" role="status"></p><p>Import the prepared chart JSON file to attach regional vintage ratings to your existing inventory. Ratings stay saved on this device and are included in your engine backup. Reimport an updated chart file to revise ratings while retaining earlier observations.</p><p>Matching requires the same year, compatible region/subregion, and any specified type, variety or appellation scope. NV and MV wines have no year-based rating. Unmatched wines stay unassessed. PDFs and screenshots must first be transcribed into an import file; this uploader accepts prepared JSON, CSV and Excel data.</p>${charts.length?`<div class="terminal-table-wrap"><table class="evidence-table"><thead><tr><th>Publication / chart</th><th>Coverage</th><th>Years</th><th>Saved assessments</th><th>Last imported</th></tr></thead><tbody>${charts.map(records=>{const r=records[0],years=records.map(x=>x.vintage);return `<tr><td>${esc(r.publication)}<small>${esc(r.chartName || 'Imported assessment')}</small></td><td>${esc(r.geography?.path.map(n=>n.name).join(' → ') || r.region)} · ${esc(r.type)}<small>${[r.style,...(r.allowedStyles || []),...(r.allowedAppellations || [])].filter(Boolean).map(esc).join(' · ')}</small></td><td>${Math.min(...years)}–${Math.max(...years)}</td><td>${records.length}</td><td>${time(records.map(x=>x.lastRetrievedAt || x.retrievedAt).sort().at(-1))}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>No vintage charts imported yet.</p>'}`);
  };
