  $('engine-preferences').onclick = () => { const p = getState().preferences; modal('Your buying preferences', `<p>Weights are normalized to their total. Missing critic evidence uses a disclosed neutral quality contribution (50/100), with zero critic coverage; missing vintage and market data use neutral 50 with zero coverage for those components; other missing evidence contributes zero; evidence coverage and every component are disclosed. Preferred-region fit adds up to 5 points, scaled by coverage.</p><form id="engine-preference-form" class="engine-form"><div class="preference-grid">${Object.entries(p.weights).map(([k, v]) => `<label>${k[0].toUpperCase() + k.slice(1)} weight<input name="${k}" type="number" min="0" max="100" value="${v}" required></label>`).join('')}</div><label>Minimum comparables for moderate confidence<input name="marketMinComparables" type="number" min="1" max="50" value="${p.marketMinComparables || 3}"></label><label>Minimum comparables for high confidence<input name="marketHighComparables" type="number" min="1" max="50" value="${p.marketHighComparables || 5}"></label><label>Market scope<select name="marketScope"><option value="US" ${(p.marketScope || 'US')==='US'?'selected':''}>US merchants only</option><option value="worldwide" ${p.marketScope==='worldwide'?'selected':''}>Worldwide</option></select></label><label>Comparison currency<input name="baseCurrency" value="${esc(p.baseCurrency || 'USD')}" maxlength="3" required></label><label>Market quote maximum age (hours)<input name="marketMaxAgeHours" type="number" min="1" max="8760" value="${p.marketMaxAgeHours}" required></label><label>Inventory maximum age (hours)<input name="inventoryMaxAgeHours" type="number" min="1" max="8760" value="${p.inventoryMaxAgeHours}" required></label><label>Automatic match confidence<input name="matchThreshold" type="number" min=".95" max="1" step=".01" value="${p.matchThreshold}" required></label><label>Preferred regions (comma-separated)<input name="preferredRegions" value="${esc(p.preferredRegions.join(', '))}"></label><button class="button primary">Save preferences and re-rank</button><p id="engine-form-message" role="status"></p></form>`, 'preferences'); };
